CREATE TABLE shows (id UUID PRIMARY KEY, name VARCHAR(200) NOT NULL, price_paise BIGINT NOT NULL CHECK (price_paise >= 0), per_user_limit INTEGER NOT NULL CHECK (per_user_limit > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reservation (id UUID PRIMARY KEY, show_id UUID NOT NULL REFERENCES shows(id), user_id VARCHAR(200) NOT NULL, amount_paise BIGINT NOT NULL CHECK (amount_paise >= 0), status VARCHAR(20) NOT NULL CHECK (status IN ('CONFIRMED','CANCELLED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE show_seat (id UUID PRIMARY KEY, show_id UUID NOT NULL REFERENCES shows(id), seat_number VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL CHECK (status IN ('AVAILABLE','HELD','CONFIRMED')), reservation_id UUID REFERENCES reservation(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_show_seat_number UNIQUE(show_id, seat_number));
CREATE TABLE reservation_seat (reservation_id UUID NOT NULL REFERENCES reservation(id), show_seat_id UUID NOT NULL REFERENCES show_seat(id), seat_number VARCHAR(30) NOT NULL, PRIMARY KEY(reservation_id, show_seat_id));
CREATE TABLE idempotency_key (id UUID PRIMARY KEY, show_id UUID NOT NULL REFERENCES shows(id), user_id VARCHAR(200) NOT NULL, idempotency_key VARCHAR(200) NOT NULL, request_hash VARCHAR(64) NOT NULL, reservation_id UUID UNIQUE REFERENCES reservation(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_idempotency_request UNIQUE(show_id,user_id,idempotency_key));
CREATE TABLE user_show_state (id UUID PRIMARY KEY, show_id UUID NOT NULL REFERENCES shows(id), user_id VARCHAR(200) NOT NULL, booked_seat_count INTEGER NOT NULL DEFAULT 0 CHECK(booked_seat_count >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_user_show_state UNIQUE(show_id,user_id));
CREATE INDEX ix_show_seat_show_status ON show_seat(show_id,status); CREATE INDEX ix_reservation_show_user ON reservation(show_id,user_id);
